import re
from difflib import SequenceMatcher
from collections import Counter
import math

_WORDS = re.compile(r"\b[a-z]+(?:'[a-z]+)?\b")

def _tokenize(text):
    return _WORDS.findall((text or "").lower())

def alignment_block_entropy(text, anchor):
    text_tokens = _tokenize(text)
    anchor_tokens = _tokenize(anchor)

    if not text_tokens or not anchor_tokens:
        return 0.5

    matcher = SequenceMatcher(None, anchor_tokens, text_tokens)
    opcodes = matcher.get_opcodes()

    if not opcodes:
        return 0.5

    block_sizes = []
    for op, i1, i2, j1, j2 in opcodes:
        size = max(i2 - i1, j2 - j1)
        if size > 0:
            block_sizes.append(size)

    if len(block_sizes) < 2:
        return 0.5

    block_freq = Counter(block_sizes)
    total = sum(block_freq.values())

    entropy = 0.0
    for count in block_freq.values():
        p = count / total
        if p > 0:
            entropy -= p * math.log2(p)

    max_entropy = math.log2(len(block_freq)) if len(block_freq) > 1 else 1.0
    if max_entropy > 0:
        normalized_entropy = entropy / max_entropy
    else:
        normalized_entropy = 0.0

    return max(0.0, min(1.0, normalized_entropy))

METRICS = {"alignment_block_entropy": alignment_block_entropy}
